 69→/**
 70→ * Initialize Core Kit singleton.
 71→ * Must be called once before any login flow.
 72→ * Matches the web app configuration exactly (same verifier, same network).
 73→ */
 74→export async function initCoreKit(): Promise<void> {
 75→  if (coreKit) return;
 76→
 77→  coreKit = new Web3AuthMPCCoreKit({
 78→    web3AuthClientId: WEB3AUTH_CLIENT_ID,
 79→    web3AuthNetwork: NETWORK_MAP[environment] || WEB3AUTH_NETWORK.DEVNET,
 80→    storage: window.localStorage,
 81→    manualSync: true,
 82→    tssLib,
 83→  });
 84→
 85→  await coreKit.init();
 86→  console.log('[CoreKit] Initialized, status:', coreKit.status);
 87→}
