 38→/**
 39→ * Application initialization sequence.
 40→ */
 41→async function init(): Promise<void> {
 42→  console.log('CipherBox Desktop initializing...');
 43→
 44→  const appDiv = document.getElementById('app');
 45→
 46→  // Show loading state
 47→  if (appDiv) {
 48→    appDiv.innerHTML = loadingHtml('Initializing CipherBox...');
 49→  }
 50→
 51→  // Step 1: Check for dev-key mode (debug builds only — command not
 52→  // registered in release builds, so invoke will reject)
 53→  let devKey: string | null = null;
 54→  try {
 55→    devKey = await invoke('get_dev_key');
 56→  } catch {
 57→    // Expected in release builds where the command isn't registered
 58→  }
 59→  if (devKey) {
 60→    if (appDiv) {
 61→      appDiv.innerHTML = loadingHtml('Dev mode: authenticating with provided key...');
 62→    }
 63→    try {
 64→      await handleDevKeyAuth(devKey);
 65→      handleAuthSuccess(appDiv);
 66→      return;
 67→    } catch (err) {
 68→      console.error('Dev-key auth failed:', err);
 69→      if (appDiv) {
 70→        appDiv.innerHTML = errorHtml(
 71→          err instanceof Error ? err.message : 'Dev-key authentication failed'
 72→        );
 73→      }
 74→      return;
 75→    }
 76→  }
 77→
 78→  // Step 2: Try silent refresh from Keychain
 79→  let silentRefreshOk = false;
 80→  try {
 81→    const refreshed: boolean = await invoke('try_silent_refresh');
 82→    if (refreshed) {
 83→      console.log('API session refreshed from Keychain');
 84→      silentRefreshOk = true;
 85→    }
 86→  } catch (err) {
 87→    console.warn('Silent refresh failed:', err);
 88→    // Not an error -- just means we need full login
 89→  }
 90→
 91→  // Step 3: Initialize Core Kit
 92→  if (appDiv) {
 93→    appDiv.innerHTML = loadingHtml('Connecting to CipherBox...');
 94→  }
 95→
 96→  try {
 97→    await initCoreKit();
 98→  } catch (err) {
 99→    console.error('Core Kit initialization failed:', err);
100→    if (appDiv) {
101→      appDiv.innerHTML = errorHtml(
102→        err instanceof Error ? err.message : 'Failed to initialize authentication'
103→      );
104→    }
105→    return;
106→  }
107→
108→  // Step 3b: If Core Kit restored a previous session, try to use it
109→  if (getCoreKitStatus() === 'LOGGED_IN') {
110→    if (silentRefreshOk) {
111→      // Both Core Kit session and API tokens are valid — restore directly
112→      try {
113→        if (appDiv) {
114→          appDiv.innerHTML = loadingHtml('Restoring session...');
115→        }
116→        await restoreSession();
117→        handleAuthSuccess(appDiv);
118→        return;
119→      } catch (err) {
120→        console.warn('Session restore failed, falling back to login:', err);
121→      }
122→    }
123→    // Core Kit has a session but API tokens are stale or restore failed —
124→    // logout Core Kit to get a clean state for fresh login
125→    console.log('Clearing stale Core Kit session before login');
126→    try {
127→      await logout();
128→    } catch {
129→      // Best-effort cleanup
130→    }
131→  }
132→
133→  // Step 4: Show login form
134→  if (appDiv) {
135→    renderLoginForm(appDiv);
136→  }
137→}
