 1→import { NestFactory } from '@nestjs/core';
 2→import { SwaggerModule, DocumentBuilder } from '@nestjs/swagger';
 3→import { ValidationPipe, Logger } from '@nestjs/common';
 4→import cookieParser from 'cookie-parser';
 5→import { AppModule } from './app.module';
 6→
 7→async function bootstrap() {
 8→  const isDev = process.env.NODE_ENV === 'development' || !process.env.NODE_ENV;
 9→
10→  // In staging/production, omit debug and verbose log levels for concise output
11→  const app = await NestFactory.create(AppModule, {
12→    logger: isDev ? ['log', 'error', 'warn', 'debug', 'verbose'] : ['log', 'error', 'warn'],
13→  });
14→
15→  const logger = new Logger('Bootstrap');
16→
17→  // [SECURITY: CRITICAL-01] Enable global validation pipe
18→  // Without this, all DTO validation decorators (@IsString, @Matches, etc.) are ignored
19→  app.useGlobalPipes(
20→    new ValidationPipe({
21→      whitelist: true, // Strip properties not in DTO
22→      forbidNonWhitelisted: true, // Reject unexpected properties
23→      transform: true, // Auto-transform types
24→    })
25→  );
26→
27→  app.use(cookieParser());
28→
29→  // CORS_ALLOWED_ORIGINS supports wildcards (e.g. https://cipher-box-pr-*.onrender.com)
30→  const rawOrigins = process.env.CORS_ALLOWED_ORIGINS;
31→  const originEntries = rawOrigins
32→    ? rawOrigins.split(',').map((s) => s.trim())
33→    : ['http://localhost:5173', 'http://localhost:4173'];
34→  const exactOrigins = originEntries.filter((o) => !o.includes('*'));
35→  const wildcardPatterns = originEntries
36→    .filter((o) => o.includes('*'))
37→    .map((o) => new RegExp(`^${o.replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*')}$`));
38→
39→  app.enableCors({
40→    origin: (
41→      origin: string | undefined,
42→      callback: (err: Error | null, allow?: boolean) => void
43→    ) => {
44→      if (!origin) return callback(null, true);
45→      if (exactOrigins.includes(origin)) return callback(null, true);
46→      if (wildcardPatterns.some((re) => re.test(origin))) return callback(null, true);
47→      callback(new Error(`Origin ${origin} not allowed by CORS`));
48→    },
49→    credentials: true,
50→  });
51→
52→  const config = new DocumentBuilder()
53→    .setTitle('CipherBox API')
54→    .setDescription('Zero-knowledge encrypted cloud storage API')
55→    .setVersion('0.1.0')
56→    .addBearerAuth()
57→    .build();
58→  const document = SwaggerModule.createDocument(app, config);
59→  SwaggerModule.setup('api-docs', app, document, {
60→    jsonDocumentUrl: 'api-docs/json',
61→  });
62→
63→  const port = process.env.PORT || 3000;
64→  await app.listen(port);
65→  logger.log(`CipherBox API running on http://localhost:${port}`);
66→  logger.log(`Swagger UI: http://localhost:${port}/api-docs`);
67→}
