  1→import { Injectable, UnauthorizedException } from '@nestjs/common';
  2→import { ConfigService } from '@nestjs/config';
  3→import { createHash, randomBytes } from 'crypto';
  4→import { getAddress } from 'viem';
  5→import { parseSiweMessage, validateSiweMessage } from 'viem/siwe';
  6→import { verifyMessage } from 'viem';
  7→
  8→@Injectable()
  9→export class SiweService {
 10→  private readonly allowedDomains: string[];
 11→
 12→  constructor(private readonly configService: ConfigService) {
 13→    const rawOrigins = this.configService.get<string>('CORS_ALLOWED_ORIGINS');
 14→    this.allowedDomains = rawOrigins
 15→      ? rawOrigins
 16→          .split(',')
 17→          .map((o) => o.trim())
 18→          .filter((o) => !o.includes('*'))
 19→          .map((o) => {
 20→            try {
 21→              const url = new URL(o);
 22→              return url.host;
 23→            } catch {
 24→              return o;
 25→            }
 26→          })
 27→      : ['localhost:5173', 'localhost:4173', 'localhost'];
 28→  }
 29→
 30→  /**
 31→   * Generate a cryptographically random nonce for SIWE.
 32→   * Returns 32 hex characters (16 random bytes).
 33→   * Exceeds EIP-4361 minimum of 8 alphanumeric characters.
 34→   */
 35→  generateNonce(): string {
 36→    return randomBytes(16).toString('hex');
 37→  }
 38→
 39→  /**
 40→   * Verify a SIWE message and signature (EOA only, no RPC needed).
 41→   * Validates the domain against CORS_ALLOWED_ORIGINS.
 42→   * Returns the verified wallet address (EIP-55 checksummed).
 43→   *
 44→   * @throws UnauthorizedException if message is invalid or signature doesn't match
 45→   */
 46→  async verifySiweMessage(
 47→    message: string,
 48→    signature: `0x${string}`,
 49→    expectedNonce: string
 50→  ): Promise<string> {
 51→    // 1. Parse the SIWE message
 52→    const parsed = parseSiweMessage(message);
 53→    if (!parsed.address) {
 54→      throw new UnauthorizedException('Invalid SIWE message: missing address');
 55→    }
 56→
 57→    // 2. Validate message fields (domain, nonce, expiry, etc.)
 58→    // Accept any domain from the allowed list (derived from CORS origins)
 59→    const isValid = this.allowedDomains.some((domain) =>
 60→      validateSiweMessage({
 61→        message: parsed,
 62→        domain,
 63→        nonce: expectedNonce,
 64→      })
 65→    );
 66→    if (!isValid) {
 67→      throw new UnauthorizedException('SIWE message validation failed');
 68→    }
 69→
 70→    // 3. Verify cryptographic signature (standalone utility, no RPC client needed)
 71→    const signatureValid = await verifyMessage({
 72→      address: parsed.address,
 73→      message,
 74→      signature,
 75→    });
 76→    if (!signatureValid) {
 77→      throw new UnauthorizedException('Invalid SIWE signature');
 78→    }
 79→
 80→    // 4. Return checksummed address
 81→    return getAddress(parsed.address);
 82→  }
 83→
 84→  /**
 85→   * Hash a wallet address for database lookup.
 86→   * Normalizes with EIP-55 checksum before hashing to ensure consistency
 87→   * regardless of input casing.
 88→   *
 89→   * @returns SHA-256 hex digest of the checksummed address (64 chars)
 90→   */
 91→  hashWalletAddress(address: string): string {
 92→    const checksummed = getAddress(address);
 93→    return createHash('sha256').update(checksummed).digest('hex');
 94→  }
 95→
 96→  /**
 97→   * Hash any identifier (email, Google sub, etc.) for database lookup.
 98→   * The caller is responsible for normalization (e.g., lowercasing email).
 99→   * Unlike hashWalletAddress, this does NOT apply EIP-55 checksumming.
100→   *
101→   * @returns SHA-256 hex digest of the value (64 chars)
102→   */
103→  hashIdentifier(value: string): string {
104→    return createHash('sha256').update(value).digest('hex');
105→  }
106→
107→  /**
108→   * Truncate a wallet address for display purposes.
109→   * Returns first 6 + "..." + last 4 characters (e.g. "0xAbCd...1234").
110→   * The full plaintext address is NEVER stored in the database.
111→   */
112→  truncateWalletAddress(address: string): string {
113→    const checksummed = getAddress(address);
114→    return `${checksummed.slice(0, 6)}...${checksummed.slice(-4)}`;
115→  }
116→
117→  /**
118→   * Truncate an email for display purposes.
119→   * Returns first 3 + "..." + last 2 of local part + full domain.
120→   * Short local parts (≤5 chars) are shown in full.
121→   * Examples: "michael@gmail.com" → "mic...el@gmail.com", "bob@x.com" → "bob@x.com"
122→   */
123→  truncateEmail(email: string): string {
124→    const atIndex = email.indexOf('@');
125→    if (atIndex === -1) return email;
126→    const local = email.slice(0, atIndex);
127→    const domain = email.slice(atIndex);
128→    if (local.length <= 5) return email;
129→    return `${local.slice(0, 3)}...${local.slice(-2)}${domain}`;
130→  }
131→}
